// seed: tests/seed.spec.ts (гость) · прод, только чтение (запись заблокирована), вход не выполняется.
import { test, expect } from '@playwright/test';
import { prepareGuest, loginPopup, readRedirectAfterLogin, LISTING_ID, LISTING_URL, LOAD } from './contact-popup.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('Связь с владельцем — возврат после входа из попапа', () => {
  for (const device of ['@desktop', '@android']) {
    test(`Объявление: «הצג מספר טלפון» → попап → SMS сохраняет возврат на это объявление #083d10 ${device} @prod-safe`, async ({ page }) => {
      await prepareGuest(page);
      await page.goto(LISTING_URL);

      await page.getByRole('button', { name: 'הצג מספר טלפון' }).first().click({ timeout: LOAD.timeout });
      const popup = loginPopup(page);
      await expect(popup, 'открылся попап входа').toBeVisible(LOAD);
      await expect(popup.getByRole('button', { name: /SMS/ })).toBeVisible();
      await expect(popup.getByRole('button', { name: /Google/ })).toBeVisible();

      await popup.getByRole('button', { name: /SMS/ }).click();

      await page.waitForURL((u) => u.pathname === '/auth' && u.searchParams.get('mode') === 'sms', LOAD);
      const saved = await readRedirectAfterLogin(page);
      expect(saved, 'redirectAfterLogin записан').not.toBeNull();
      const target = new URL(saved!, 'https://x');
      expect(target.pathname, 'возврат — на страницу объявления').toBe('/businessdetail');
      expect(target.searchParams.get('id'), 'возврат — на это же объявление').toBe(LISTING_ID);
      expect(target.searchParams.get('contact'), 'с пометкой связи contact=1').toBe('1');
    });
  }
});
